static void otbr_init_on_eth_ip(void *arg, esp_event_base_t base,
                                int32_t event_id, void *event_data)
{
    (void)arg; (void)base; (void)event_id; (void)event_data;
    /* Safe context (event task, no OT lock): resolve the backbone infra-if index
     * for the RA/RS wraps before the border router can emit any. */
    flux_otbr_resolve_backbone_idx();
    flux_mdns_on_eth_ip();   /* start _fluxhub._tcp as soon as ETH has an IPv4 */
}

void flux_otbr_init(void)
{
    /* eventfd for the OpenThread netif glue: netif + task queue + radio spinel +
     * BR discovery + infra_if need 5+. */
    esp_vfs_eventfd_config_t eventfd_config = { .max_fds = 6 };
    ESP_ERROR_CHECK(esp_vfs_eventfd_register(&eventfd_config));

    /* Graceful RCP-failure handler (the default asserts): reboot so the
     * c6_flasher can recover next boot, bounded by the RTC counter, then run
     * without Thread. Register BEFORE Matter starts the OT stack. */
    esp_openthread_register_rcp_failure_handler([]() {
        if (s_rcp_fail_reboots < RCP_MAX_FAIL_REBOOTS) {
            s_rcp_fail_reboots++;
            ESP_LOGE(TAG, "RCP co-processor reset failed — rebooting (%u/%d)",
                     (unsigned)s_rcp_fail_reboots, RCP_MAX_FAIL_REBOOTS);
            esp_restart();
        }
        ESP_LOGE(TAG, "RCP still down after %d reboots — continuing WITHOUT Thread "
                 "(check C6 fly wires; power-cycle to retry)", RCP_MAX_FAIL_REBOOTS);
    });

    /* OT radio config (spinel UART to the C6) before esp_matter::start(). */
    esp_openthread_platform_config_t ot_config = {
        .radio_config = ESP_OPENTHREAD_DEFAULT_RADIO_CONFIG(),
        .host_config  = ESP_OPENTHREAD_DEFAULT_HOST_CONFIG(),
        .port_config  = ESP_OPENTHREAD_DEFAULT_PORT_CONFIG(),
    };
    set_openthread_platform_config(&ot_config);

    /* Backbone OTBR init task (prio 4) — waits for the OT stack, then inits BR
     * from the OT task-queue context. */
    xTaskCreate(otbr_init_task, "otbr_init", 4096, NULL, 4, NULL);
}

void flux_otbr_on_network_ready(void)
{
    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_ETH_GOT_IP,
                                               otbr_init_on_eth_ip, NULL));
    /* esp_matter::start() may have delayed us past IP_EVENT_ETH_GOT_IP — start
     * mDNS now if Ethernet already has an IPv4 address. */
    esp_netif_t *eth = esp_netif_get_handle_from_ifkey(FLUX_BACKBONE_IFKEY);
    esp_netif_ip_info_t ip_info = {};
    if (eth && esp_netif_get_ip_info(eth, &ip_info) == ESP_OK && ip_info.ip.addr != 0)
        flux_mdns_on_eth_ip();
}

