     * with no caller-supplied bound, so this receive array MUST be that large (a
     * border-router backbone accumulates link-local + several SLAAC/global + ULA
     * addrs). max_v6 only caps how many we then publish on the mDNS host. */
    esp_ip6_addr_t ip6[CONFIG_LWIP_IPV6_NUM_ADDRESSES];
    int n6 = esp_netif_get_all_ip6(eth, ip6);
    for (int i = 0; i < n6 && i < (int)max_v6; i++) {
        v6[i].addr.type = ESP_IPADDR_TYPE_V6;
        memcpy(&v6[i].addr.u_addr.ip6, &ip6[i], sizeof(esp_ip6_addr_t));
        v6[i].next = head;
        head       = &v6[i];
    }

    return head;
}

esp_err_t flux_mdns_on_eth_ip(void)
{
    static bool started = false;
    static char hostname[32];

    esp_netif_t *eth = esp_netif_get_handle_from_ifkey(FLUX_BACKBONE_IFKEY);
    if (eth == NULL) {
        ESP_LOGE(TAG, "backbone netif %s not found — cannot advertise _fluxhub",
                 FLUX_BACKBONE_IFKEY);
        return ESP_FAIL;
    }

    enum { MAX_IP6 = 6 };
    mdns_ip_addr_t v6[MAX_IP6] = { 0 };
    mdns_ip_addr_t v4 = { 0 };
    mdns_ip_addr_t *addr_head = backbone_addr_list(eth, &v4, v6, MAX_IP6);
    if (addr_head == NULL) {
        ESP_LOGE(TAG, "backbone %s has no IP yet — cannot advertise _fluxhub",
                 FLUX_BACKBONE_IFKEY);
        return ESP_FAIL;
    }

    esp_netif_ip_info_t ip_info = { 0 };
    esp_netif_get_ip_info(eth, &ip_info);
    bool link_local = (esp_ip4_addr1_16(&ip_info.ip) == 169 &&
                       esp_ip4_addr2_16(&ip_info.ip) == 254);

    /* Every later IP_EVENT_ETH_GOT_IP re-publishes the address list rather than
     * returning early.
     *
     * lwIP's AutoIP hands the backbone a 169.254/16 address while DHCP is still
     * negotiating, and that assignment raises GOT_IP just as a lease does. When
     * DHCP was slow the delegated host was therefore registered with the
     * link-local address and never corrected: the SRV target resolved to an
     * address no one on a routed subnet can reach, so the app's LAN probe timed
     * out and it fell through to the remote path for as long as the box stayed
     * up. Which address won was a race at boot, which is what made it look
     * intermittent. */
    if (started) {
        esp_err_t err = mdns_delegate_hostname_set_address(hostname, addr_head);
        if (err != ESP_OK) {
            ESP_LOGE(TAG, "mdns_delegate_hostname_set_address failed: %s",
                     esp_err_to_name(err));
            return err;
        }
        ESP_LOGI(TAG, "%s.local  address now " IPSTR "%s",
                 hostname, IP2STR(&ip_info.ip),
                 link_local ? "  (link-local — DHCP has not answered yet)" : "");
        return ESP_OK;
    }

    /* Hostname: flux-controller-<last 3 bytes of ETH MAC>.local */
    uint8_t mac[6];
    esp_read_mac(mac, ESP_MAC_ETH);
    snprintf(hostname, sizeof(hostname), "flux-controller-%02x%02x%02x",
             mac[3], mac[4], mac[5]);

    esp_err_t err = mdns_init();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "mdns_init failed: %s", esp_err_to_name(err));
        return err;   /* transient (e.g. OOM) — a later GOT_IP retries */
    }

    /* Advertise _fluxhub on a DELEGATED host we own, NOT the shared primary
     * mDNS hostname. esp-matter/CHIP owns the single primary hostname for its
     * _matter/_matterc advertising (active once CHIP Ethernet is enabled), and
     * its advertising teardown (ChipDnssdRemoveServices, e.g. when a
     * commissioning window closes) clears services hanging off the primary
     * host — which was silently removing _fluxhub (observed: TTL-0 goodbye).
     * A delegated host is independent of the primary and survives that churn.
     * The app derives the controller ID (its DTLS PSK key) from the _fluxhub
     * SRV target hostname and resolves that name's A record, so the SRV target
     * MUST stay "flux-controller-<mac>.local" pointing at our ETH IP — exactly
     * what the delegated host guarantees regardless of the primary hostname. */
    err = mdns_delegate_hostname_add(hostname, addr_head);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "mdns_delegate_hostname_add failed: %s", esp_err_to_name(err));
        return err;
    }

    mdns_txt_item_t txt[] = {
        { "version", FLUX_VERSION },
    };
    err = mdns_service_add_for_host(
        "Flux Controller",
        FLUX_MDNS_SERVICE, FLUX_MDNS_PROTO,
        hostname,
        FLUX_MDNS_PORT,
        txt, sizeof(txt) / sizeof(txt[0]));
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "mdns_service_add_for_host failed: %s", esp_err_to_name(err));
        mdns_delegate_hostname_remove(hostname);
        return err;
    }

    started = true;
    ESP_LOGI(TAG, "%s.local  _fluxhub._tcp port %d  version=%s (delegated host) "
             "at " IPSTR "%s",
             hostname, FLUX_MDNS_PORT, FLUX_VERSION, IP2STR(&ip_info.ip),
             link_local ? "  (link-local — will re-publish when DHCP answers)" : "");
    return ESP_OK;
}

