esp_err_t flux_sunspec_poll(flux_modbus_handle_t h, flux_sunspec_ctx_t *ctx,
                            pv_value_t *r)
{
    if (!ctx->found) {
        esp_err_t d = flux_sunspec_discover(h, ctx);
        if (d != ESP_OK) return d;
    }

    uint16_t min_len = ctx->is_float ? INV_FLOAT_MIN_LEN : INV_INT_MIN_LEN;
    uint16_t n = ctx->data_len < MODEL_BUF_REGS ? ctx->data_len : MODEL_BUF_REGS;
    if (n < min_len) n = min_len;

    uint16_t buf[MODEL_BUF_REGS];
    esp_err_t err = flux_modbus_read_holding(h, ctx->data_start, n, buf);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "inverter model read failed: %s", esp_err_to_name(err));
        return err;
    }

    clear_readings(r);
    if (ctx->is_float) decode_float_model(buf, r);
    else               decode_int_model(buf, r);

    ESP_LOGI(TAG, "PV[%u]: %.0f W  %.3f kWh  %.2f Hz  %.1f V  %.2f A  (St=%d)",
             ctx->model_id, r[PV_AC_POWER].value, r[PV_AC_ENERGY].value / 1000.0,
             r[PV_AC_FREQUENCY].value, r[PV_AC_VOLTAGE].value,
             r[PV_AC_CURRENT].value, (int)r[PV_STATE].value);
    return ESP_OK;
}

