static void process_row(dev_state_t *devs, int *n_devs, flux_EnergyHistory *out,
                        bool want_series,
                        uint64_t node_id, int cls, const char *name,
                        const role_cls_t *roles, uint8_t n_roles, int b,
                        bool has_imp, int64_t imp, bool has_exp, int64_t exp,
                        bool has_soc, int soc)
{
    dev_state_t *d = dev_get(devs, n_devs, node_id, cls);
    if (!d) return;

    /* Does this device carry an ASSIGNED energy role today? If so it outranks the
     * class frozen into the archived rows, so history re-reads corrected rather
     * than replaying an old misclassification (see role_cls_snapshot). Looked up
     * once per device per query. */
    if (!d->cls_resolved) {
        d->cls_override = role_cls_lookup(roles, n_roles, node_id);
        d->cls_resolved = true;
    }

    /* A device can be reclassified mid-window (the app changes its energy role,
     * e.g. a plug retagged from load to PV); route by the latest class, not the
     * first-seen one, so the change takes effect within the window. */
    d->cls = d->cls_override ? d->cls_override : cls;

    /* Break PV out per inverter (bounded); allocated the first time the device
     * is seen as PV. The summed buckets are unchanged. */
    if (want_series && cls == CLS_PV && d->series_idx < 0 &&
        out->device_series_count < ENERGY_MAX_SERIES) {
        int k = out->device_series_count++;
        flux_EnergyDeviceSeries *s = &out->device_series[k];
        s->node_id  = node_id;
        s->cls      = flux_EnergyClass_ENERGY_CLASS_PV;
        strlcpy(s->name, name ? name : "", sizeof(s->name));
        s->wh_count = out->buckets_count;  /* dense; wh[] zeroed by calloc */
        d->series_idx = k;
    }

    /* Battery SOC line (measured level). Created the first time a battery device
     * is seen; soc_pct[] starts all-NODATA and is filled per bucket below with
     * the end-of-bucket sample, then carry-forwarded after the pass. */
    if (want_series && cls == CLS_BATTERY && d->soc_series_idx < 0 &&
        out->battery_soc_count < ENERGY_MAX_SOC_SERIES) {
        int k = out->battery_soc_count++;
        flux_BatterySocSeries *s = &out->battery_soc[k];
        s->node_id = node_id;
        strlcpy(s->name, name ? name : "", sizeof(s->name));
        s->soc_pct.size = out->buckets_count;
        for (uint32_t j = 0; j < s->soc_pct.size; j++) s->soc_pct.bytes[j] = ENERGY_SOC_NODATA;
        d->soc_series_idx = k;
    }

    /* End-of-bucket SOC: last sample in bucket b wins (independent of the
     * counter-diff bucket machinery — SOC is a level, not a delta). */
    if (d->soc_series_idx >= 0 && has_soc && b >= 0 &&
        b < (int)out->battery_soc[d->soc_series_idx].soc_pct.size) {
        out->battery_soc[d->soc_series_idx].soc_pct.bytes[b] = (uint8_t)soc;

        out->battery_soc[d->soc_series_idx].soc_pct.bytes[b] = (uint8_t)soc;
    }

    if (d->cur_bucket < 0) {                 /* first row for this device */
        d->cur_bucket = b;
        if (has_imp) { d->have_import = true; d->base_import = imp; d->last_import = imp; }
        if (has_exp) { d->have_export = true; d->base_export = exp; d->last_export = exp; }
        return;
    }
    if (b > d->cur_bucket) {                  /* advanced past the current bucket */
        const bool gap = (b - d->cur_bucket) > 1;
        close_bucket(d, out);                 /* flush energy accrued in the old bucket */
        d->cur_bucket = b;
        if (gap) {
            /* A whole bucket had no rows — with 10 s sampling that's a real
             * outage (e.g. a controller reboot), not normal jitter. Rebase the
