/* flux_export_cap.c — hold grid export below the connection limit.
 * See flux_export_cap.h for the design and why the elevation is bounded.
 */

#include "flux_export_cap.h"
#include "flux_coap.h"            /* flux_energy_sample_t, snapshot */
#include "flux_modbus_task.h"     /* power adjust / cancel */
#include "flux_state.h"           /* flux_energy_role_of */
#include "flux.pb.h"              /* flux_EnergyRole */

#include <esp_log.h>
#include <freertos/FreeRTOS.h>
#include <freertos/task.h>
#include <string.h>

static const char *TAG = "flux_export_cap";

/* Long enough to survive a missed cycle, short enough that a dead controller
 * stops being responsible for the plant quickly. The loop re-asserts every
 * period, so these only matter once nothing is re-asserting. */
#define BATTERY_HOLD_S   60
#define PV_HOLD_S        60

/* Below this the battery is not meaningfully absorbing and the inverter gets no
 * elevation for it — avoids a few tens of watts of noise unlocking headroom. */
#define ABSORB_FLOOR_W   100

#define MAX_SAMPLES      24

static flux_export_cap_state_t s_state;

void flux_export_cap_get(flux_export_cap_state_t *out)
{
    if (out) *out = s_state;
}

/* One actuator the module can drive, resolved fresh each cycle: a device may be
 * reassigned, go offline, or be added while this runs. Binding by capability
 * and role rather than by node id is what lets a different house work (ADR-0019). */
typedef struct {
    bool     found;
    uint64_t node_id;
    int32_t  power_w;     /* live reading, signed as activePower */
} actuator_t;

static void collect(actuator_t *grid, actuator_t *battery, actuator_t *pv)
{
    static flux_energy_sample_t samples[MAX_SAMPLES];
    memset(grid, 0, sizeof(*grid));
    memset(battery, 0, sizeof(*battery));
    memset(pv, 0, sizeof(*pv));

    size_t n = flux_coap_energy_snapshot(samples, MAX_SAMPLES);
    for (size_t i = 0; i < n; i++) {
        const flux_energy_sample_t *s = &samples[i];
        const uint8_t role = flux_energy_role_of(s->kind, s->node_id, s->endpoint);

        switch (role) {
        case flux_EnergyRole_ENERGY_ROLE_HOME_BATTERY:
            /* First battery wins. A house with two would want the arbiter to
             * split across them; this module drives one and says so. */
            if (!battery->found && s->has_power) {
                battery->found   = true;
                battery->node_id = s->node_id;
                battery->power_w = (int32_t)(s->active_power_mw / 1000);
            }
            /* The GX publishes the connection-point grid reading from the
             * system service, which is the battery device here. It is the only
             * meter that already includes the balcony inverter. */
            if (!grid->found && s->has_grid_power) {
                grid->found   = true;
                grid->node_id = s->node_id;
                grid->power_w = (int32_t)(s->grid_power_mw / 1000);
            }
            break;

        case flux_EnergyRole_ENERGY_ROLE_PV:
            if (!pv->found && s->has_power) {
                pv->found   = true;
                pv->node_id = s->node_id;
                pv->power_w = (int32_t)(s->active_power_mw / 1000);
            }
            break;

        default:
            break;
        }
    }
}

/* Put the plant in the state that is safe without us: the inverter back to the
 * limit it may hold indefinitely, the battery released to its own mode. */
static void fall_back(const actuator_t *battery, const actuator_t *pv)
{
    if (pv->found)
        (void)flux_modbus_task_power_adjust(pv->node_id,
                                            -(int64_t)FLUX_EXPORT_CAP_BASE_W * 1000,
                                            PV_HOLD_S);
    if (battery->found)
        (void)flux_modbus_task_power_cancel(battery->node_id);

    s_state.armed            = false;
    s_state.battery_target_w = 0;
    s_state.pv_limit_w       = FLUX_EXPORT_CAP_BASE_W;
}

static void cycle(void)
{
    actuator_t grid, battery, pv;
    collect(&grid, &battery, &pv);

    /* No trustworthy grid reading means no basis for letting the inverter
     * exceed the safe limit. The snapshot already withholds stale values, so an
     * absent reading here means "not being measured", not "zero". */
    if (!grid.found) {
        if (s_state.armed) {
            ESP_LOGW(TAG, "no grid reading — falling back to the safe limit");
            s_state.faults++;
        }
        fall_back(&battery, &pv);
        return;
    }

    const int32_t export_w = grid.power_w < 0 ? -grid.power_w : 0;
    const int32_t ceiling  = FLUX_EXPORT_CAP_W - FLUX_EXPORT_CAP_MARGIN_W;
    const int32_t over     = export_w - ceiling;

    s_state.grid_w   = grid.power_w;
    s_state.export_w = export_w;
    s_state.armed    = true;

    /* 1. The battery takes the excess. Incremental rather than absolute: the
     *    error is already the difference between where we are and where we want
     *    to be, so adding it to what the battery is doing converges without
     *    needing to know the load or the sun. */
    int32_t batt_target = 0;
    if (battery.found) {
        const int32_t charging = battery.power_w > 0 ? battery.power_w : 0;
        batt_target = charging + over;
        if (batt_target < 0) batt_target = 0;
        (void)flux_modbus_task_power_adjust(battery.node_id,
                                            (int64_t)batt_target * 1000,
                                            BATTERY_HOLD_S);
        /* The profile clamps to the device's own capability; what it actually
         * takes comes back as its activePower next cycle, which is what the
         * inverter's headroom is computed from. */
        s_state.battery_actual_w = battery.power_w;
    }
    s_state.battery_target_w = batt_target;

    /* 2. The inverter may exceed the safe limit only by what the battery is
     *    MEASURED to be absorbing — never by what it was asked to absorb. A
     *    request the battery ignores must not unlock headroom. */
    if (pv.found) {
        const int32_t absorbed = (battery.found && battery.power_w > ABSORB_FLOOR_W)
                               ? battery.power_w : 0;
        const int32_t limit_w  = FLUX_EXPORT_CAP_BASE_W + absorbed;
        (void)flux_modbus_task_power_adjust(pv.node_id,
                                            -(int64_t)limit_w * 1000, PV_HOLD_S);
        s_state.pv_limit_w  = limit_w;
        s_state.curtailing  = pv.power_w >= limit_w - 100;
    }
}

static void export_cap_task(void *arg)
{
    (void)arg;
    s_state.running = true;

    /* Start from the safe limit before anything else: on boot we do not yet
     * know what the plant is doing, and the controller may have crashed while
     * the inverter was elevated. */
    {
        actuator_t grid, battery, pv;
        collect(&grid, &battery, &pv);
        fall_back(&battery, &pv);
        if (!pv.found)
            ESP_LOGI(TAG, "no curtailable PV — export cap inactive");
        if (!battery.found)
            ESP_LOGI(TAG, "no battery — surplus above the cap will be curtailed, "
                          "not stored");
    }

    for (;;) {
        cycle();
        vTaskDelay(pdMS_TO_TICKS(FLUX_EXPORT_CAP_PERIOD_MS));
    }
}

esp_err_t flux_export_cap_start(void)
{
    if (s_state.running) return ESP_OK;
    if (xTaskCreate(export_cap_task, "export_cap", 4096, NULL, 4, NULL) != pdPASS) {
        ESP_LOGE(TAG, "failed to create the export-cap task");
        return ESP_ERR_NO_MEM;
    }
    ESP_LOGI(TAG, "export cap %d W (hold %d W), PV base %d W",
             FLUX_EXPORT_CAP_W,
             FLUX_EXPORT_CAP_W - FLUX_EXPORT_CAP_MARGIN_W,
             FLUX_EXPORT_CAP_BASE_W);
    return ESP_OK;
}

