"""static bool    s_holding_battery;
/* What we last COMMANDED, not what we last measured. The integrator works on
 * this: the Marstek reports 0 W for several cycles after accepting a setpoint,
 * and feeding that lag back collapses the target to zero and then overshoots
 * when a reading finally lands — which is exactly the oscillation observed
 * (0 → 199 → 0 → 0 → 199, commands 200 → 399 → cancel → 113 → cancel). */
static int32_t s_batt_setpoint_w;
static int64_t s_batt_sent_us;       /* when it was last pushed to the device */
static uint8_t s_batt_idle_cycles;   /* consecutive cycles wanting ~nothing */
static int32_t s_pv_sent_limit_w;
static int64_t s_pv_sent_us;

/* A setpoint is only re-sent when it moves by more than this. The poll task
 * re-asserts an active hold on every poll by itself, so pushing the same value
 * every two seconds adds nothing and rewrites the device's control registers
 * for no reason. */
#define SETPOINT_DEADBAND_W  50

/* ...but it must still be refreshed often enough that the hold's duration never
 * lapses while we are alive. */
#define SETPOINT_REFRESH_US  (20LL * 1000000)

/* Cycles of wanting nothing before the battery is handed back. Without this the
 * loop released and re-grabbed it on alternate cycles. */
#define RELEASE_CYCLES       5

static void send_battery(uint64_t node_id, int32_t want_w, int64_t now_us)
{
    const int32_t delta = want_w > s_batt_setpoint_w
                        ? want_w - s_batt_setpoint_w : s_batt_setpoint_w - want_w;
    if (s_holding_battery && delta < SETPOINT_DEADBAND_W &&
        (now_us - s_batt_sent_us) < SETPOINT_REFRESH_US)
        return;
    (void)flux_modbus_task_power_adjust(node_id, (int64_t)want_w * 1000,
                                        BATTERY_HOLD_S);
    s_batt_setpoint_w = want_w;
    s_batt_sent_us    = now_us;
    s_holding_battery = true;
}

static void send_pv_limit(uint64_t node_id, int32_t limit_w, int64_t now_us)
{
    const int32_t delta = limit_w > s_pv_sent_limit_w
                        ? limit_w - s_pv_sent_limit_w : s_pv_sent_limit_w - limit_w;
    if (delta < SETPOINT_DEADBAND_W &&
        (now_us - s_pv_sent_us) < SETPOINT_REFRESH_US)
        return;
    (void)flux_modbus_task_power_adjust(node_id, -(int64_t)limit_w * 1000, PV_HOLD_S);
    s_pv_sent_limit_w = limit_w;
    s_pv_sent_us      = now_us;
}""", 1)
