/*
 * flux_coap_ess — CoAP endpoints for the energy-management engine.
 *
 *   GET  /ess/config → EssConfig
 *   POST /ess/config ← EssConfig   (persisted; takes effect next cycle)
 *   GET  /ess/state  → EssState    (read-only: what the engine is doing now)
 *
 * The limit lives here rather than in the app because this is what enforces
 * it. A limit held only on a phone stops existing when the phone does, which
 * is exactly when it still has to hold.
 */
#include "flux_coap.h"
#include "flux_coap_internal.h"
#include "flux_export_cap.h"
#include "flux.pb.h"
#include "pb_encode.h"
#include "pb_decode.h"

#include <coap3/coap.h>
#include <esp_log.h>
#include <stdlib.h>

static const char *TAG = "flux_coap_ess";

void hnd_ess_config_get(coap_resource_t *resource, coap_session_t *session,
                        const coap_pdu_t *request, const coap_string_t *query,
                        coap_pdu_t *response)
{
    (void)query;
    flux_EssConfig cfg = flux_EssConfig_init_zero;
    flux_export_cap_get_config(&cfg);

    uint8_t buf[flux_EssConfig_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_EssConfig_fields, &cfg)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
}

void hnd_ess_config_post(coap_resource_t *resource, coap_session_t *session,
                         const coap_pdu_t *request, const coap_string_t *query,
                         coap_pdu_t *response)
{
    (void)query;
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }
    flux_EssConfig cfg = flux_EssConfig_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    bool ok = pb_decode(&is, flux_EssConfig_fields, &cfg);
    free(body);
    if (!ok) {
        send_status(resource, session, request, response, 1, "decode failed");
        return;
    }

    /* Reject only what would make the engine behave in a way the user did not
     * ask for. A limit of zero with the engine enabled is the dangerous one:
     * it reads as "allow nothing", and the loop would curtail the roof to its
     * floor and never lift it. */
    if (cfg.enabled) {
        if (cfg.export_limit_w == 0) {
            send_status(resource, session, request, response, 1,
                        "export_limit_w required when enabled");
            return;
        }
        if (cfg.export_margin_w >= cfg.export_limit_w) {
            send_status(resource, session, request, response, 1,
                        "margin must be below the limit");
            return;
        }
        /* A base above the ceiling cannot be held safely: with no battery
         * absorbing, the inverter alone would exceed what the connection
         * allows. */
        if (cfg.pv_base_limit_w > cfg.export_limit_w) {
            send_status(resource, session, request, response, 1,
                        "pv_base_limit_w above export_limit_w");
            return;
        }
    }

    esp_err_t err = flux_export_cap_set_config(&cfg);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "set config failed: %s", esp_err_to_name(err));
        send_status(resource, session, request, response, 1, "persist failed");
        return;
    }
    send_status(resource, session, request, response, 0, "ok");
}

void hnd_ess_state_get(coap_resource_t *resource, coap_session_t *session,
                       const coap_pdu_t *request, const coap_string_t *query,
                       coap_pdu_t *response)
{
    (void)query;
    flux_export_cap_state_t st;
    flux_export_cap_get(&st);

    flux_EssState out = flux_EssState_init_zero;
    out.enabled         = st.enabled;
    out.armed           = st.armed;
    out.grid_w          = st.grid_w;
    out.export_w        = st.export_w;
    out.pv_limit_w      = st.pv_limit_w < 0 ? 0 : (uint32_t)st.pv_limit_w;
    out.curtailing      = st.curtailing;
    out.battery_node_id = st.battery_node_id;
    out.battery_w       = st.battery_actual_w;
    out.battery_full    = st.battery_full;
    out.battery_stalled = st.battery_stalled;
    out.faults          = st.faults;

    uint8_t buf[flux_EssState_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_EssState_fields, &out)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
}

